import UIKit
struct Room { let id: Int; var title: String }
let old = Room(id: 91, title: "Кухня")
let updated = Room(id: 91, title: "Большая кухня")
var store = [old.id: old]
store[updated.id] = updated
var snapshot = NSDiffableDataSourceSnapshot<Int, Int>()
snapshot.appendSections([0])
snapshot.appendItems([old.id])
snapshot.reconfigureItems([updated.id])
assert(snapshot.itemIdentifiers == [91])
assert(store[91]?.title == "Большая кухня")

Идентичность — Int id, содержимое обновлено в store. reconfigureItems отмечает повторную настройку после последующего apply.

