import UIKit
let layout = UICollectionViewCompositionalLayout { _, environment in
    let width = environment.container.effectiveContentSize.width
    let fraction: CGFloat = width >= 600 ? 0.25 : 0.5
    let size = NSCollectionLayoutSize(
        widthDimension: .fractionalWidth(fraction),
        heightDimension: .estimated(80)
    )
    let item = NSCollectionLayoutItem(layoutSize: size)
    let groupSize = NSCollectionLayoutSize(
        widthDimension: .fractionalWidth(1), heightDimension: .estimated(80)
    )
    let count = width >= 600 ? 4 : 2
    let group = NSCollectionLayoutGroup.horizontal(
        layoutSize: groupSize, subitems: Array(repeating: item, count: count)
    )
    return NSCollectionLayoutSection(group: group)
}

Выбор зависит от контейнера layout, а не глобального размера экрана. Итоговая геометрия требует отдельной раскладки UIKit.
